        title = LocalizedText("""Novena de Corpus Christi al Santísimo Cuerpo y Sangre de Cristo""", """Corpus Christi Novena""", """Novena de Corpus Christi"""),
        patron = LocalizedText("""Santo patrón de el Santísimo Sacramento, la Eucaristía, la Presencia Real""", """Patron saint of Blessed Sacrament, Eucharist, Real Presence""", """Novena de Corpus Christi"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Reza esta novena de Corpus Christi y haz crecer tu amor por la Eucaristía, con una devoción que transforma, a la Presencia Real de Cristo: Cuerpo, Sangre, Alma y Divinidad.""", """Deepen your love for the Eucharist. Pray this Corpus Christi novena now and experience transforming devotion to Christ’s Real Presence - Body, Blood, Soul, and Divinity.""", """Santo padroeiro de Santíssimo Sacramento, Eucaristia, Presença Real"""),
        miraculousHistory = LocalizedText("", "", ""),
